NAME = 'Est: Estonian Bible'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Jeesuse Kristuse Ilmutus, mille Jumal Temale andis, et Ta näitaks Tema sulastele, mis varsti peab sündima; ja seda Ta näitas, läkitades Oma Ingli kaudu Oma sulasele Johannesele,',
        2: 'kes on tunnistanud Jumala sõna ja Jeesuse Kristuse tunnistust, kõike, mida ta on näinud.',
        3: 'Õnnis on see, kes loeb, ja need, kes kuulevad selle prohvetliku kuulutuse sõnu ja peavad tallel, mis sellesse on kirja pandud; sest aeg on ligidal.',
        4: 'Johannes seitsmele Aasia kogudusele: armu teile ja rahu Sellelt, Kes on ja Kes oli ja Kes tuleb; ja neilt seitsmelt vaimult, kes on Tema aujärje ees;',
        5: 'ja Jeesuselt Kristuselt, Kes on ustav tunnistaja, esmasündinu surnute seast ja maailma kuningate valitseja. Temale, Kes meid on armastanud ja meid on vabastanud meie pattudest Oma Verega,',
        6: 'ja on meid teinud kuningriigiks, preestriks Jumalale ja Oma Isale, Temale olgu au ja vägi ajastute ajastuteni! Aamen.',
        7: 'Vaata, Tema tuleb pilvedega ja kõik silmad saavad Teda näha, ja need, kes Tema läbi pistsid, ja kõik maa suguharud tõstavad kaebehäält Tema pärast. Tõepoolest, aamen!',
        8: '"Mina olen A ja O", ütleb Issand Jumal, Kes on ja Kes oli ja Kes tuleb, Kõigeväeline.',
        9: 'Mina, Johannes, teie vend ja teie kaaslane viletsuses ja kuningriigis ja kannatlikkuses Jeesuses, olin saarel, mida kutsutakse Patmoseks, Jumala sõna ja Jeesuse Kristuse tunnistuse pärast.',
        10: 'Ma olin vaimus Issanda päeval ja kuulsin oma selja taga suurt, otsekui pasuna häält,',
        11: 'mis ütles: "Mida sa näed, kirjuta raamatusse ja läkita neile seitsmele kogudusele: Efesosse ja Smürnasse ja Pergamoni ja Tüatiirasse ja Sardesesse ja Filadelfiasse ja Laodikeasse!"',
        12: 'Ja ma pöördusin ümber vaatama seda häält, mis minuga rääkis. Ja kui ma olin pöördunud, nägin ma seitset kuld küünlajalga.',
        13: 'Ja keset neid seitset küünlajalga üht, kes oli Inimese Poja sarnane, riietatud pika rüüga ja vöötatud rinde alt kuldvööga.',
        14: 'Tema pea ja juuksed olid valged nagu valge vill, nagu lumi, ja Tema silmad nagu tuleleek;',
        15: 'ja Tema jalad olid otsekui ahjus hõõguv, hiilgav vasemaak ja Tema hääl oli nagu suurte vete kohin.',
        16: 'Ja Temal oli paremas käes seitse taevatähte, ja Tema suust läks välja terav kaheterane mõõk, ja Tema pale oli otsekui päike, kui see paistab oma väes.',
        17: 'Kui ma Teda nägin, siis ma langesin maha Tema jalgade ette nagu surnu. Ja Ta pani Oma parema käe mu peale ja ütles mulle: "Ära karda, Mina olen Esimene ja Viimne',
        18: 'ja Elav; Ma olin surnud, ja vaata, Ma olen elav ajastute ajastuteni, ja Minu käes on surma ja surmavalla võtmed!',
        19: 'Kirjuta siis, mida sa oled näinud ja mis nüüd on ja mis pärast seda sünnib!',
        20: 'Nende seitsme taevatähe saladus, mida sa nägid Minu paremas käes, ja nende seitsme kuldküünlajala saladus on see: need seitse tähte on seitsme koguduse Inglid, ja need seitse küünlajalga on seitse kogudust!',
    },
    2: {
        1: 'Efesose koguduse Inglile kirjuta: nõnda ütleb see, Kes neid seitset tähte peab Oma paremas käes, Kes kõnnib seitsme kuldküünlajala vahel:',
        2: 'Ma tean su tegusid ja sinu tööd ja su kannatlikkust ja et sa ei või sallida kurje ja oled läbi katsunud need, kes endid ütlevad Apostlid olevat, aga ei ole, ning oled leidnud nad olevat valelikud;',
        3: 'ja sinul on kannatlikkust ja sa oled kandnud raskusi Minu nime pärast ega ole raugenud.',
        4: 'Aga Mul on sinu vastu, et sa oled maha jätnud oma esimese armastuse.',
        5: 'Siis mõtle nüüd, kust sa oled langenud, ja paranda meelt ja tee esimesi tegusid; aga kui mitte, siis Ma tulen su juurde ja lükkan su küünlajala tema asemelt ära, kui sa meelt ei paranda.',
        6: 'Aga see sul on, et sa vihkad nikolaiitide tegusid, mida vihkan Minagi.',
        7: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb: kes võidab, sellele ma annan süüa elupuust, mis on Jumala paradiisis.',
        8: 'Ja Smürna koguduse Inglile kirjuta: nõnda ütleb Esimene ja Viimne, Kes oli surnud ja on saanud elavaks:',
        9: 'Ma tean su viletsust ning vaesust - kuid sa oled siiski rikas - ja pilkamist nende poolt, kes ütlevad endid juudid olevat, aga ei ole, vaid on saatana kogudus!',
        10: 'Ära karda seda, mida sul tuleb kannatada! Vaata, kurat tahab visata mõned teie seast vangitorni, et teid kiusataks; ja teil on viletsust kümme päeva. Ole ustav surmani, siis Ma annan sulle elukrooni!',
        11: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb: kes võidab, sellele ei tee teine surm mingit kahju!',
        12: 'Ja Pergamoni koguduse Inglile kirjuta: nõnda ütleb See, Kelle käes on terav kaheterane mõõk:',
        13: 'Ma tean, kus sa elad: seal, kus on saatana aujärg! Ja sa pead kinni Mu nimest ega ole Minu usku salanud ka neil päevil, mil Antipas, Mu tunnistaja, mu ustav, tapeti teie juures, kus saatan elab.',
        14: 'Aga Mul on pisut sinu vastu, et sul on seal neid, kes peavad kinni Bileami õpetusest, kes Baalakit õpetas võrgutama Iisraeli sööma ebajumalate ohvreid ja hoorama.',
        15: 'Samuti on sul ka neid, kes samasuguselt kinni peavad nikolaiitide õpetusest.',
        16: 'Paranda siis meelt; aga kui mitte, siis Ma tulen su juurde nobedasti ja sõdin nende vastu oma suu mõõgaga!',
        17: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb: kes võidab, sellele Ma annan süüa varjule pandud mannat ja annan temale valge kivikese ja kivikese peale kirjutatud uue nime, mida ükski muu ei tunne kui aga see, kes selle saab.',
        18: 'Ja Tüatiira koguduse Inglile kirjuta: nõnda ütleb Jumala Poeg, Kellel on silmad nagu tuleleek ja jalad hiilgavad otsekui vasemaak:',
        19: 'Ma tean sinu tegusid ja armastust ja usku ja teenimist ja kannatlikkust, ja et sinu viimseid tegusid on rohkem kui esimesi.',
        20: 'Aga Mul on sinu vastu, et sa sallid naist Iisebeli, kes ennast nimetab prohvetiks ja õpetab ning ahvatleb Minu sulaseid hoorama ja sööma ebajumalate ohvreid.',
        21: 'Ma olen temale andnud aega meeleparanduseks, aga ta ei taha pöörduda oma porduelust.',
        22: 'Vaata, Ma viskan ta haigevoodisse ja need, kes temaga abielu rikuvad, suurde viletsusse, kui nad ei pöördu tema tegudest!',
        23: 'Ja tema lapsed Ma lõpetan surmaga, ja kõik kogudused tunnevad ära, et Mina olen See, Kes katsub läbi neerud ja südamed, ja Ma annan teile igaühele teie tegude järgi.',
        24: 'Aga teile Ma ütlen ja muile Tüatiiras olevaile, kellel ei ole seda õpetust ja kes ei ole, nagu nad ütlevad, ära tundnud saatana sügavusi: Ma ei pane teile peale muud koormat,',
        25: 'pidage vaid kinni, mis teil on, kuni Ma tulen!',
        26: 'Ja kes võidab ja otsani peab Minu tegusid, sellele Ma annan meelevalla paganate üle',
        27: 'ja ta peab neid karjatama raudkepiga, nõnda nagu saviastjad pihuks lüüakse, otsekui Minagi olen saanud meelevalla Oma Isalt;',
        28: 'ja Mina annan temale koidutähe.',
        29: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb!',
    },
    3: {
        1: 'Ja Sardese koguduse Inglile kirjuta: nõnda ütleb See, Kelle on seitse Jumala vaimu ja need seitse tähte: Ma tean sinu tegusid, et sul on nimi, et sa elad, aga oled surnud!',
        2: 'Saa valvsaks ja kinnita muid, kes on suremas; sest Mina ei ole leidnud, et su teod oleksid täielikud Minu Jumala ees!',
        3: 'Siis mõtle, kuidas sa sõna vastu võtsid ja kuulsid, ja pea seda ning paranda meelt! Kui sa nüüd ei valva, tulen Ma kui varas ja sina ei tea, mil tunnil Ma su peale tulen.',
        4: 'Ometi on sul ka Sardeses mõned nimed, kes ei ole reostanud oma riideid, ja nad peavad Minuga käima valgeis riideis, sest nad on seda väärt.',
        5: 'Kes võidab, see riietatakse nõnda valgete riietega ja Mina ei kustuta tema nime eluraamatust, ja Ma tahan tunnistada tema nime Oma Isa ees ja kõigi Tema Inglite ees.',
        6: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb!',
        7: 'Ja Filadelfia koguduse Inglile kirjuta: nõnda ütleb Püha, Tõeline, Kelle käes on Taaveti võti ja Kes avab ja ükski ei sule; Kes suleb ja ükski ei ava:',
        8: 'Ma tean sinu tegusid. Vaata, Ma olen seadnud su ette avatud ukse ja ükski ei suuda seda sulgeda; sest sul on pisut rammu, ja sa oled pidanud Mu sõna ega ole salanud Mu nime!',
        9: 'Vaata, Ma annan saatana kogudusest mõned, kes ütlevad endid juudid olevat, aga ei ole, vaid valetavad! Vaata, Ma teen, et nad tulevad ja kummardavad sinu jalgade ette ja tunnevad ära, et Ma sind olen armastanud!',
        10: 'Et sa Mu kannatlikkuse sõna oled pidanud, siis Minagi tahan sind hoida kiusatustunni eest, mis on tulemas kogu maailma peale neid kiusama, kes maa peal elavad.',
        11: 'Ma tulen nobedasti; pea kinni, mis sul on, et ükski sinu krooni ei võtaks!',
        12: 'Kes võidab, selle Ma teen sambaks Oma Jumala templis, ja tema ei lähe sealt enam välja, ja Ma kirjutan tema peale Oma Jumala nime ja Oma Jumala linna nime, Uue Jeruusalemma, mis maha tuleb taevast Minu Jumala juurest, ja Oma uue nime.',
        13: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb!',
        14: 'Ja Laodikea koguduse Inglile kirjuta: nõnda ütleb Aamen, ustav ja tõeline tunnistaja, Jumala loodu algus:',
        15: 'Ma tean sinu tegusid, et sa pole külm ega kuum. Oh, oleksid sa külm või kuum!',
        16: 'Aga nüüd, et sa oled leige ja mitte külm ega kuum, siis tahan Ma sind välja sülitada Oma suust!',
        17: 'Sa ju ütled: ma olen rikas ja mul on vara küllalt ega ole mul midagi vaja. Ja sa ei teagi, et sa oled vilets ja armetu ja vaene ja pime ja alasti!',
        18: 'Ma annan sulle nõu osta Minult kulda, mis tules on puhastatud, et sa võiksid rikkaks saada, ja valged riided, et sa nendega riietuksid ja ei nähtaks sinu alastuse häbi, ja silmasalvi võida silmi, et sa näeksid.',
        19: 'Ma noomin ja karistan kõiki, keda Ma armastan. Ole siis väga hoolas ja paranda meelt!',
        20: 'Vaata, Ma seisan ukse taga ja koputan: kui keegi Mu häält kuuleb ja ukse avab, selle juurde Ma lähen sisse ja söön õhtust ühes temaga ja tema Minuga!',
        21: 'Kes võidab, sellele Ma annan istuda ühes Minuga Minu aujärjel, nõnda nagu Minagi olen võitnud ja istunud ühes Oma Isaga Tema aujärjele.',
        22: 'Kellel kõrv on, see kuulgu, mis Vaim kogudustele ütleb!',
    },
    4: {
        1: 'Pärast seda ma nägin, ja vaata: uks oli avatud taevas ja endine hääl, mida olin kuulnud otsekui pasunat rääkivat minuga, ütles: "Astu siia üles, ja Ma näitan sulle, mis pärast seda peab sündima!"',
        2: 'Ja sedamaid olin mina vaimus. Ja vaata, aujärg seisis taevas, ja Keegi istus aujärjel!',
        3: 'Ja See, Kes istus, oli jumelt otsekui jaspise- ja sardisekivi, ja vikerkaar oli aujärje ümber, jumelt sarnane smaragdikivile.',
        4: 'Ja aujärje ümber oli kakskümmend neli aujärge; ja aujärgedel ma nägin istuvat kahtkümmend nelja vanemat, riietatud valgeisse riietesse ja kuldpärjad peas.',
        5: 'Ja aujärjest väljus välke ja hääli ja piksemürinat, ja seitse tulist lampi põles aujärje ees; need on Jumala seitse vaimu.',
        6: 'Ja aujärje ees oli otsekui klaasmeri, mägikristalli sarnane; ja keset aujärge ja aujärje ümber oli neli olendit, täis silmi eest ja tagant.',
        7: 'Ja esimene olend oli lõukoera sarnane, ja teine olend oli härja sarnane, ja kolmandal olendil oli nägu otsekui inimesel, ja neljas olend oli lendava kotka sarnane.',
        8: 'Ja neil neljal olendil oli igaühel kuus tiiba, ümberringi ja seestpoolt nad olid täis silmi. Nad ei lakka ööd ja päevad ütlemast: "Püha, püha, püha on Issand Jumal, Kõigeväeline, Kes oli ja Kes on ja Kes tuleb!"',
        9: 'Ja nii sageli kui olendid annavad austust, au ja tänu Sellele, Kes aujärjel istub ja elab ajastute ajastuteni,',
        10: 'heidavad need kakskümmend neli vanemat maha selle ette, Kes aujärjel istub, ja nad kummardavad Teda, Kes elab ajastute ajastuteni, ja panevad oma pärjad maha aujärje ette ning ütlevad:',
        11: 'Sina, meie Issand ja Jumal, oled väärt võtma austust ja au ja väge, sest sina oled loonud kõik asjad, ja Sinu tahte läbi on need olemas ja on loodud!"',
    },
    5: {
        1: 'Ja ma nägin Selle paremas käes, Kes istus aujärjel, rullraamatut, täis kirjutatud seestpoolt ja väljastpoolt ja kinni pandud seitsme pitseriga.',
        2: 'Ja ma nägin vägevat Inglit; see kuulutas suure häälega: "Kes on vääriline avama seda raamatut ja lahti võtma selle pitsereid?"',
        3: 'Ja ükski ei võinud ei taevas ega maa peal ega maa all avada raamatut ega vaadata sinna sisse.',
        4: 'Ja mina nutsin väga, et kedagi ei leitud väärt olevat avama raamatut ja vaatama sinna sisse.',
        5: 'Ja üks vanemaist ütles mulle: "Ära nuta! Vaata, lõukoer Juuda suguharust, Taaveti juur, on võitnud nii, et Tema võib avada raamatu ja lahti võtta selle seitse pitserit!"',
        6: 'Ja ma nägin keset aujärge ja nelja olendit ja keset vanemaid seismas Talle, Kes oli otsekui tapetud; ja Tal oli seitse sarve ja seitse silma, mis on Jumala seitse vaimu, kes on läkitatud kogu ilmamaale.',
        7: 'Ja Ta tuli ja võttis raamatu selle paremast käest, Kes istus aujärjel.',
        8: 'Ja kui Ta oli võtnud raamatu, siis need olendid ja need kakskümmend neli vanemat heitsid maha Talle ette, ja igaühel oli käes kannel ja kuldkausid, täis suitsutusrohte; need on pühade palved.',
        9: 'Ja nad laulsid uut laulu ning ütlesid: "Sina oled väärt võtma raamatut ja lahti tegema selle pitsereid, sest Sina oled olnud tapetud ja oled Oma Verega Jumalale ostnud inimesi kõigist suguharudest ja keeltest ja rahvaist ja paganahõimudest',
        10: 'ja oled nad teinud kuningriigiks ja preestriks meie Jumalale, ja nad valitsevad maa peal."',
        11: 'Ja ma nägin ja kuulsin paljude Inglite häält aujärje ja olendite ja vanemate ümbert; ja nende arv oli kümme tuhat korda kümme tuhat ja tuhat korda tuhat.',
        12: 'Ja need ütlesid suure häälega: "Tall, Kes on tapetud, on väärt võtma väge ja rikkust ja tarkust ja rammu ja au ja austust ja kiitust!"',
        13: 'Ja kõike loodut, mis on taevas ja maa peal ja maa all ja meres, ja kõike, mis nendes on, kuulsin ma ütlevat: "Sellele, Kes istub aujärjel, ja Tallele olgu kiitus ja au ja austus ja vägi ajastute ajastuteni!"',
        14: 'Ja need neli olendit ütlesid: "Aamen!" Ja vanemad heitsid maha ja kummardasid.',
    },
    6: {
        1: 'Ja ma nägin, kuidas Tall võttis lahti ühe seitsmest pitserist, ja ma kuulsin üht neljast olendist otsekui pikse häälega ütlevat: "Tule!"',
        2: 'Ja ma vaatasin, ja näe: valge hobune; ja ta seljas istujal oli amb käes; ja talle anti pärg ja ta väljus võites ja võitu saavutama.',
        3: 'Ja kui Tall võttis lahti teise pitseri, kuulsin ma teist olendit ütlevat: "Tule!"',
        4: 'Ja väljus teine hobune, tulipunane, ja ta seljas istujal lasti rahu maa pealt ära võtta, et inimesed üksteist tapaksid; ja temale anti suur mõõk.',
        5: 'Ja kui Tall võttis lahti kolmanda pitseri, kuulsin ma kolmandat olendit ütlevat: "Tule!" Ja ma vaatasin, ja näe: must hobune, ja tema seljas istujal olid kaalud käes.',
        6: 'Ja ma kuulsin otsekui häält nelja olendi keskelt ütlevat: "Mõõt nisu teenari eest ja kolm mõõtu otri teenari eest; ja õlile ega viinale ära tee kahju!"',
        7: 'Ja kui Ta võttis lahti neljanda pitseri, kuulsin ma neljanda olendi häält ütlevat: "Tule!"',
        8: 'Ja ma vaatasin, ja näe, tuhkur hobune, ja kes tema seljas istus, selle nimi oli Surm, ja Surmavald käis ühes temaga; ja neile anti meelevald neljanda osa ilmamaa üle, tappa mõõga ja nälja ja surmaga ja maapealsete kiskjate elajate abil.',
        9: 'Ja kui Ta võttis lahti viienda pitseri, siis ma nägin altari all nende hingi, kes olid tapetud Jumala sõna pärast ja tunnistuse pärast, mis neil oli.',
        10: 'Ja nad kisendasid suure häälega ning ütlesid: "Oh Püha ja Tõeline Valitseja, kui kaua Sa ei mõista kohut ega tasu kätte meie verd neile, kes elavad maa peal?"',
        11: 'Ja neile anti igaühele pikk valge rüü, ja neile öeldi, et nad oleksid rahul veel natuke aega, kuni saab täis nende kaassulaste ja nende vendade arv, kes tapetakse nõnda nagu nemadki.',
        12: 'Ja ma nägin, kui Ta võttis lahti kuuenda pitseri, et siis sündis suur maavärisemine, ja päike läks mustaks nagu karvane kotiriie ja kuu läks kogunisti nagu vereks;',
        13: 'ja taevatähed kukkusid maha, otsekui viigipuu ajab maha oma toored marjad, kui suur tuul teda raputab;',
        14: 'ja taevas veeres ära nagu rullraamat, ja kõik mäed ja saared nihkusid oma paigust;',
        15: 'ja ilmamaa kuningad ja suured isandad ja sõjapealikud ja rikkad ja võimumehed ja kõik orjad ja kõik vabad pugesid varjule koobastesse ja mägede kaljudesse,',
        16: 'ja nad ütlesid mägedele ja kaljudele: "Langege meie peale ja varjake meid Selle palge eest, Kes aujärjel istub, ja Talle viha eest!',
        17: 'Sest on tulnud Tema suur vihapäev, ja kes võib püsida?"',
    },
    7: {
        1: 'Pärast seda ma nägin nelja Inglit seisvat maa neljal nurgal ning kinni pidavat nelja maatuult, et ükski tuul ei puhuks maa peale ega mere peale ega ühegi puu peale.',
        2: 'Ja ma nägin teist Inglit tõusvat päevatõusu poolt, ning ta käes oli elava Jumala pitsat, ja tema hüüdis suure häälega nendele neljale Inglile, kellele oli antud teha kahju maale ja merele,',
        3: 'ning ütles: "Ärge tehke kahju maale ega merele ega puudele, enne kui me oleme pannud pitseri oma Jumala sulaste otsaesisele!"',
        4: 'Ja ma kuulsin nende arvu, kes olid pitseriga märgitud, sada nelikümmend neli tuhat pitseriga märgitut kõigist Iisraeli laste suguharudest:',
        5: 'Juuda suguharust kaksteist tuhat pitseriga märgitut; Ruubeni suguharust kaksteist tuhat; Gaadi suguharust kaksteist tuhat;',
        6: 'Aaseri suguharust kaksteist tuhat; Naftali suguharust kaksteist tuhat; Manasse suguharust kaksteist tuhat;',
        7: 'Siimeoni suguharust kaksteist tuhat; Leevi suguharust kaksteist tuhat; Issaskari suguharust kaksteist tuhat;',
        8: 'Sebuloni suguharust kaksteist tuhat; Joosepi suguharust kaksteist tuhat; Benjamini suguharust kaksteist tuhat pitseriga märgitut.',
        9: 'Pärast seda ma nägin, ja vaata, suur hulk rahvast, keda ükski ei võinud ära lugeda kõigist rahvahõimudest ja suguharudest ja rahvaist ja keeltest; need seisid aujärje ees ja Talle ees, riietatud valgeisse rüüdesse ja palmioksad käes.',
        10: 'Ja nad hüüdsid suure häälega ja ütlesid: "Õnnistus meie Jumalale, Kes aujärjel istub, ja Tallele!"',
        11: 'Ja kõik Inglid seisid aujärje ja vanemate ja nelja olendi ümber ja heitsid aujärje ette silmili maha ja kummardasid Jumalat',
        12: 'ning ütlesid: "Aamen, kiitus ja austus ja tarkus ja tänu ja au ja vägi ja ramm meie Jumalale ajastute ajastuteni! Aamen."',
        13: 'Ja üks vanemaist hakkas kõnelema ning ütles minule: "Need seal valgeis rüüdes, kes nad on ja kust nad tulid?"',
        14: 'Ja ma ütlesin temale: "Mu isand, sina tead!" Ja ta ütles mulle: "Need on, kes tulevad suurest viletsusest ja on oma rüüd pesnud ja oma rüüd valgeks teinud Talle Veres!',
        15: 'Sellepärast on nad Jumala aujärje ees ja teenivad Teda ööd ja päevad Tema templis. Ja See, Kes aujärjel istub, laotab Oma telgi nende üle.',
        16: 'Neil ei ole siis enam nälga ega janu; ka ei lange nende peale päikest ega mingisugust palavat;',
        17: 'sest Tall, Kes on keset aujärge, hoiab neid ja juhatab nad elava vee allikaile; ja Jumal pühib ära kõik pisarad nende silmist!"',
    },
    8: {
        1: 'Ja kui Tall võttis lahti seitsmenda pitseri, tekkis taevas vaikus ligi pooleks tunniks.',
        2: 'Ja ma nägin seitset Inglit, kes seisid Jumala ees, ja neile anti seitse pasunat.',
        3: 'Ja teine Ingel tuli ja astus altari äärde, kuldsuitsutusastja käes, ja talle anti palju suitsutusrohte, et ta neid lisaks kõigi pühade palvetele kuldaltaril, mis oli aujärje ees.',
        4: 'Ja suitsutusrohtude suits pühade palvetega tõusis Ingli käest Jumala ette.',
        5: 'Ja Ingel võttis suitsutusastja ja täitis selle tulega altarilt ja viskas ta maa peale. Siis sündis hääli ja mürinaid ja välke ning maavärisemine.',
        6: 'Ja need seitse Inglit, kelle käes oli seitse pasunat, valmistusid pasunat puhuma.',
        7: 'Ja esimene puhus pasunat. Siis tuli rahet ja tuld verega segamini ja paisati maa peale. Ja kolmas osa maad põles ära ja kolmas osa puid põles ära ja kõik haljas rohi põles ära.',
        8: 'Ja teine Ingel puhus pasunat. Siis heideti merre otsekui suur mägi, mis tules põles, ja kolmas osa merd sai vereks.',
        9: 'Ja kolmas osa mere loomi, kellel hing sees, suri ära ja kolmas osa laevu läks hukka.',
        10: 'Ja kolmas Ingel puhus pasunat. Siis kukkus taevast maha suur täht, mis põles otsekui tõrvalont ja langes kolmanda osa jõgede peale ja veeallikate peale.',
        11: 'Ja tähe nimi on Koirohi. Ja kolmas osa vetest muutus koirohuks, ja palju inimesi suri vete kätte, sest need olid mõruks läinud.',
        12: 'Ja neljas Ingel puhus pasunat. Siis löödi kolmas osa päikest ja kolmas osa kuud ja kolmas osa tähti, nii et kolmas osa neist pimeneks ja kolmas osa päeva ei paistaks, ja ööd niisamuti.',
        13: 'Ja ma nägin ja kuulsin kotka lendavat kesktaeva all ning suure häälega ütlevat: "Häda, häda, häda neile, kes elavad maa peal, nende kolme Ingli järgneva pasunahääle pärast, kes veel peavad pasunat puhuma!"',
    },
    9: {
        1: 'Ja viies Ingel puhus pasunat. Siis ma nägin tähe taevast maa peale kukkunud olevat, ja temale anti sügavuse kaevu võti.',
        2: 'Ja ta avas sügavuse kaevu, ja kaevust tõusis suits otsekui suure ahju suits. Ja päike ja õhk läksid pimedaks kaevu suitsust.',
        3: 'Ja suitsust väljusid rohutirtsud maa peale ja neile anti meelevald, nagu skorpionidel on meelevald maa peal.',
        4: 'Ja neile öeldi, et nad ei tohi kurja teha ei maa rohule ega millelegi, mis haljas on, ega ühelegi puule, vaid ainult inimestele, kellel ei ole Jumala pitserit otsaesisel.',
        5: 'Ja neile anti käsk, et nad neid ei tapaks, vaid et nad neid piinaksid viis kuud; ja nende piinamine on otsekui skorpioni piinamine, kui ta inimest nõelab.',
        6: 'Ja neil päevil inimesed otsivad surma ega leia seda mitte, ja püüavad surra, aga surm põgeneb nende eest!',
        7: 'Ja rohutirtsud olid välimuselt sõjaks valmistatud hobuste sarnased ja neil olid peas pärjad otsekui kullast ja nende nägu oli nagu inimeste nägu;',
        8: 'ja neil olid juuksed nagu naiste juuksed ja nende hambad olid otsekui lõukoerte hambad.',
        9: 'Ja neil olid soomusrüüd, otsekui raudrüüd, ja nende tiibade kahin oli otsekui vankrite mürin, kui palju hobuseid jookseb sõtta.',
        10: 'Ja neil olid sabad ja astlad nagu skorpionidel, ja nende sabades oli võim inimestele kahju teha viis kuud.',
        11: 'Ja neil oli kuningaks sügavuse Ingel; tema nimi on heebrea keeli Abadoon ja kreeka keeli Apollüon.',
        12: 'Esimene häda on möödas; vaata, kaks häda tuleb veel pärast seda!',
        13: 'Ja kuues Ingel puhus pasunat. Siis ma kuulsin üht häält Jumala ees oleva kuldaltari neljast nurgast;',
        14: 'see ütles kuuendale Inglile, kelle käes oli pasun: "Päästa lahti need neli Inglit, kes on seotud suure Eufrati jõe ääres!"',
        15: 'Siis päästeti lahti neli Inglit, kes on valmis tunniks ja päevaks ja kuuks ja aastaks, et tappa kolmas osa inimesi.',
        16: 'Ja ratsaväelaste arv on kakskümmend tuhat korda kümme tuhat; ma kuulsin nende arvu.',
        17: 'Ja nõnda ma nägin nägemuses hobuseid ja nende seljas istujaid, ja neil olid tulekarva ja purpursinised ja väävlikarva soomusrüüd; ja hobuste pead olid nagu lõukoerte pead, ja nende suust käis välja tuld ja suitsu ja väävlit.',
        18: 'Neist kolmest nuhtlusest sai surma kolmas osa inimesi tule ja suitsu ja väävli läbi, mis nende hobuste suust välja käis.',
        19: 'Sest hobuste võim on nende suus ja nende sabades; sest nende sabad on madude sarnased; neil on pead ja nendega nad teevad kahju.',
        20: 'Aga järelejäänud inimesed, keda neis nuhtlustes ei surmatud, ei pöördunud siiski mitte oma käte tegudest, et nad poleks kummardanud kurje vaime ning kuld- ja hõbe- ja vask- ja kivi- ja puujumalaid, kes ei või näha ega kuulda ega kõndida.',
        21: 'Ja nad ei pöördunud oma tapmistest ega oma nõidustest, ei oma hoorusest ega oma vargustest.',
    },
    10: {
        1: 'Ja ma nägin teist vägevat Inglit taevast maha tulevat; see oli riietatud pilvega ja vikerkaar oli tema pea kohal, ja tema pale oli otsekui päike ja tema jalad nagu tulesambad.',
        2: 'Ja tema käes oli avatud raamatuke, ja ta pani oma parema jala mere ja vasaku maa peale.',
        3: 'Ja ta kisendas suure häälega, otsekui lõukoer möirgab. Ja kui ta kisendas, siis hakkasid seitse pikset müristama oma häältega.',
        4: 'Ja kui need seitse pikset oma häältega olid rääkinud, tahtsin ma kirjutada. Siis ma kuulsin häält taevast ütlevat: "Pane pitseriga kinni, mis seitse pikset on kõnelnud, ja ära kirjuta seda!"',
        5: 'Ja Ingel, keda ma nägin seisvat mere ja maa peal, tõstis oma käe taeva poole',
        6: 'ja vandus Selle juures, Kes elab ajastute ajastuteni, Kes on loonud taeva ja mis seal on ja maa ja mis seal on ja mere ja mis seal on, et aega ei saa enam olema,',
        7: 'vaid seitsmenda Ingli hääle päevil, kui ta hakkab pasunat puhuma, läheb täide Jumala saladus, nõnda nagu Ta seda rõõmsat sõnumit on kuulutanud prohvetitele, Oma sulastele!',
        8: 'Ja hääl, mida ma taevast kuulsin, rääkis jälle minuga ja ütles: "Mine võta avatud raamatuke Ingli käest, kes seisab mere ja maa peal!"',
        9: 'Ja ma läksin Ingli juurde ning ütlesin temale: "Anna mulle see raamatuke!" Ja tema ütles mulle: "Võta ja söö see ära! Ja see peab su kõhus olema mõru, aga su suus magus nagu mesi!"',
        10: 'Ja ma võtsin raamatukese Ingli käest ja sõin selle ära. Ja see oli mu suus magus nagu mesi. Ja kui ma selle olin söönud, sai see mu kõhus mõruks!',
        11: 'Ja minule öeldi: "Sa pead veel ennustama rahvaste ja rahvahõimude ja keelte ja paljude kuningate kohta!"',
    },
    11: {
        1: 'Siis anti mulle kepi sarnane pilliroog ning öeldi: "Tõuse ja mõõda Jumala tempel ja altar ja need, kes seal kummardavad;',
        2: 'aga väljaspool templit olev õu jäta kõrvale ja ära seda mõõda, sest see on antud paganaile. Ja nad tallavad püha linna nelikümmend ja kaks kuud.',
        3: 'Ja mina annan Oma kahele tunnistajale meelevalla kotiriidesse riietatuina prohvetlikult kuulutada tuhat kakssada kuuskümmend päeva.',
        4: 'Nemad on need kaks õlipuud ja kaks küünlajalga, mis seisavad ilmamaa Issanda ees.',
        5: 'Ja kui keegi tahab neile kurja teha, siis väljub tuli nende suust ja sööb nende vaenlased; kui keegi tahab neile kurja teha, siis peab see nõnda tapetama.',
        6: 'Neil on meelevald sulgeda taevas, et nende prohvetliku kuulutamise päevil ei sajaks vihma, ja neil on meelevald vete üle muuta neid vereks ja lüüa maad igasuguse nuhtlusega nii sageli kui nad vaid tahavad.',
        7: 'Ja kui nad oma tunnistuse on lõpetanud, siis hakkab metsaline, kes tõuseb sügavusest, nendega sõda pidama ja võidab nad ära ja surmab nad.',
        8: 'Ja nende kehad vedelevad suure linna tänavail, mida vaimulikult hüütakse Soodomaks ja Egiptuseks, kus ka nende Issand risti löödi.',
        9: 'Ja rahvaste ja suguharude ja keelte ja rahvahõimude seast nähakse nende kehi kolm ja pool päeva ja nende kehi ei lasta hauda panna.',
        10: 'Ja need, kes maa peal elavad, rõõmustuvad nendest ja on väga rõõmsad ning läkitavad ande üksteisele, sest et need kaks prohvetit vaevasid neid, kes maa peal elavad."',
        11: 'Ja pärast neid kolme ja poolt päeva läks elu vaim Jumalast nende sisse ja nad tõusid püsti oma jalgele, ja suur kartus tuli nende peale, kes neid vaatasid.',
        12: 'Ja nad kuulsid suurt häält taevast neile ütlevat: "Tulge siia üles!" Ja nad läksid üles taevasse pilves, ja nende vaenlased vaatasid neid.',
        13: 'Ja samal tunnil sündis suur maavärisemine, ja kümnes osa linna langes maha, ja selles maavärisemises sai surma inimesi seitse tuhat nime. Siis teised lõid kartma ja andsid taeva Jumalale austust.',
        14: 'Teine häda on möödas, vaata, kolmas häda tuleb varsti!',
        15: 'Ja seitsmes Ingel puhus pasunat. Siis sündisid suured hääled taevas ning ütlesid: "Maailma valitsus on saanud meie Issanda ja Tema Kristuse omaks, ja Tema valitseb ajastute ajastuteni"',
        16: 'Ja need kakskümmend neli vanemat, kes istuvad Jumala ees oma aujärgedel, heitsid silmili maha ja kummardasid Jumalat',
        17: 'ning ütlesid: "Me täname Sind, Issand, kõigeväeline Jumal, Kes oled ja Kes olid, et sa oled võtnud kätte Oma suure väe ja oled saanud kuningaks.',
        18: 'Ja paganrahvad on vihastunud, kuid Sinu viha on tulnud, ja tulnud on aeg mõista kohut surnutele ja kätte anda palk Su sulastele-prohvetitele ja pühadele ja neile, kes kardavad Sinu nime, pisukestele ja suurtele, ja hävitada need, kes hävitavad maad!"',
        19: 'Ja Jumala tempel taevas avanes ja Tema seaduselaegast nähti Tema templis. Siis sündis välke ja hääli ja mürinat ja maavärisemine ja suur rahesadu!',
    },
    12: {
        1: 'Ja suur imetäht ilmus taevas: naine, riietatud päikesega ja kuu tema jalge all, ja temal peas pärg kaheteistkümnest tähest.',
        2: 'Ta oli käima peal ja kisendas lapsevaevas ja tal oli suur valu sünnitades.',
        3: 'Ja teine imetäht ilmus taevas, ja vaata, suur tulipunane lohe, seitsme peaga ja kümne sarvega, ja ta peade peal seitse ehissidet.',
        4: 'Tema saba pühkis ära kolmanda osa taevatähti ja viskas need maa peale. Ja lohe seisis naise ees, kes oli sünnitamas, et niipea kui ta on sünnitanud, neelata laps.',
        5: 'Ja naine tõi ilmale poeglapse, kes peab raudkepiga karjatama kõiki paganrahvaid. Ja naise laps kisti Jumala ja Tema aujärje juurde.',
        6: 'Ja naine põgenes kõrbe, kus temal oli Jumalast valmistatud ase, et teda seal toidetaks tuhat kakssada kuuskümmend päeva.',
        7: 'Ja sõda tõusis taevas: Miikael ja tema Inglid sõdisid lohe vastu, ja lohe sõdis ja tema Inglid.',
        8: 'Ja ta ei saanud võimust ja nende aset ei leitud enam taevast.',
        9: 'Ja suur lohe, see vana madu, keda hüütakse Kuradiks ja Saatanaks, kes eksitab kogu maailma, visati maa peale, ja tema Inglid visati välja ühes temaga.',
        10: 'Ja ma kuulsin suurt häält taevast ütlevat: "Nüüd on õnnistus ja vägi ja kuninglik valitsus saanud meie Jumala ja meelevald Tema Kristuse kätte, sest välja on visatud meie vendade süüdistaja, kes nende peale kaebab meie Jumala ees päevad ja ööd!',
        11: 'Ja nemad on tema võitnud Talle vere tõttu ja oma tunnistuse sõna tõttu ega ole oma elu armastanud surmani.',
        12: 'Seepärast olge väga rõõmsad, taevad, ja teie, kes seal sees elate! Häda maale ja merele, sest kurat on tulnud maha teie juurde ja tal on suur viha, sest ta teab, et tal on pisut aega!"',
        13: 'Ja kui lohe nägi, et ta oli visatud maa peale, ta kiusas taga naist, kes oli ilmale toonud poeglapse.',
        14: 'Ja naisele anti kaks suure kotka tiiba, et ta lendaks kõrbe oma paika, kus teda toidetakse aeg ja ajad ja pool aega eemal mao palge eest.',
        15: 'Ja madu purskas oma suust vett naisele järele otsekui jõge, et teda jõevooluga ära uhtuda.',
        16: 'Aga maa aitas naist: maa avas oma suu ja neelas ära jõe, mille lohe oma suust välja ajas.',
        17: 'Ja lohe sai vihaseks naise peale ja läks sõdima nendega, kes naise soost olid üle jäänud ja kes peavad Jumala käske ja kellel on Jeesuse tunnistus.',
    },
    13: {
        1: 'Ja ma nägin metsalist tõusvat merest. Sel oli seitse pead ja kümme sarve ja tema sarvede peal kümme ehissidet ja tema peade peal Jumala pilkenimesid.',
        2: 'Ja metsaline, keda ma nägin, oli pantri sarnane, ja tema jalad olid nagu karu jalad ja tema suu nagu lõukoera suu, ja lohe andis temale oma väe ja oma aujärje ja suure võimu.',
        3: 'Ja ma nägin ühe tema peadest olevat nagu surmavalt haavatud; ja tema surmahaav paranes. Ja kogu ilmamaa imetles jälgides metsalist,',
        4: 'ja nad kummardasid lohet, et ta metsalisele oli andnud selle võimu, ja kummardasid metsalist ning ütlesid: "Kes on metsalise sarnane ja kes suudab sõdida tema vastu?"',
        5: 'Ja temale anti suu rääkida suurustamise ja jumalapilke sõnu, ja temale anti meelevald tegutseda nelikümmend ja kaks kuud.',
        6: 'Ja ta avas oma suu pilkamiseks Jumala vastu, et pilgata Tema nime ja tema telki, neid, kes taevas elavad.',
        7: 'Ja temale anti võimus pidada sõda pühadega ja nad ära võita; ja temale anti meelevald iga suguharu ja rahva ja keele ja rahvahõimu üle.',
        8: 'Ja teda hakkavad kummardama kõik, kes maa peal elavad, kelle nimed maailma algusest ei ole kirjutatud tapetud Talle eluraamatusse.',
        9: 'Kui kellelgi on kõrv, siis ta kuulgu!',
        10: 'Kui keegi viib vangi, siis ta ise satub vangi; kui keegi tapab mõõgaga, siis tapetakse teda ennast mõõgaga. Siin on pühade kannatlikkus ja usk.',
        11: 'Ja ma nägin teist metsalist tõusvat maa seest; ja sel oli kaks sarve otsekui tallel ja ta rääkis nagu lohe.',
        12: 'Ja ta teeb kõik esimese metsalise võimuga tema ees. Ja ta teeb, et maa ja need, kes seal peal elavad, kummardavad esimest metsalist, kelle surmahaav oli paranenud.',
        13: 'Ja ta teeb suuri tunnustähti, nõnda et ta inimeste ees laseb tuldki tulla taevast alla maa peale.',
        14: 'Ja ta eksitab neid, kes maa peal elavad, tunnustähtedega, mis temale on antud teha esimese metsalise ees, ning käsib neid, kes maa peal elavad, teha kuju metsalisele, kellel oli mõõga haav ja kes virgus ellu.',
        15: 'Ja temale anti meelevald anda metsalise kujule vaim, et ka metsalise kuju räägiks ja teeks, et need, kes iialgi ei kummarda metsalise kuju, ära tapetaks.',
        16: 'Ja tema teeb, et kõik, nii pisukesed kui suured, nii rikkad kui vaesed, nii vabad kui orjad, võtavad märgi oma parema käe peale või oma otsaesisele,',
        17: 'ja et ükski muu ei saa osta ega müüa kui aga see, kellel on see märk: metsalise nimi või tema nime arv.',
        18: 'Siin on tarkus! Kellel on mõistust, see arvaku ära metsalise arv; sest see on inimese arv. Ja tema arv on kuussada kuuskümmend kuus.',
    },
    14: {
        1: 'Ja ma nägin, ja vaata, Tall seisis Siioni mäel ja ühes Temaga sada nelikümmend neli tuhat, kellele oli otsaesisele kirjutatud Tema Isa nimi.',
        2: 'Ja ma kuulsin häält taevast otsekui hulga vete kohisemist ja nagu suure müristamise häält; ja hääl, mida ma kuulsin, oli otsekui kandlelööjate hääl, kes löövad oma kandleid.',
        3: 'Ja nemad laulsid uut laulu aujärje ees ja nende nelja olendi ja vanemate ees. Ja ükski ei võinud seda laulu õppida kui aga need sada nelikümmend neli tuhat, kes on ära ostetud ilmamaalt.',
        4: 'Need on need, kes endid ei ole rüvetanud naistega, sest nad on neitsilikud; need on, kes Talle järgivad, kuhu Ta iganes läheb; need on inimeste seast ära ostetud esianniks Jumalale ja Tallele,',
        5: 'ja nende suust ei ole leitud kavalust; nemad on veatud.',
        6: 'Ja ma nägin teist Inglit lendavat kesktaeva kohal; sellel oli igavene Evangeelium, et armuõpetust kuulutada neile, kes elavad maa peal, ja kõigile rahvahõimudele ja suguharudele ja keeltele ja rahvastele.',
        7: 'Ja ta ütles suure häälega: "Kartke Jumalat ja andke Temale austust, sest on tulnud Tema kohtutund, ja kummardage Teda, Kes on teinud taeva ja maa ja mere ja veteallikad!"',
        8: 'Ja veel teine Ingel järgnes temale ning ütles: "Langenud, langenud on suur linn Baabülon, kes oma hooruskiima viinaga on jootnud kõiki rahvaid!"',
        9: 'Ja veel kolmas Ingel järgnes neile ning ütles suure häälega: "Kui keegi kummardab metsalist ja tema kuju ja võtab tema märgi oma otsaesisele või oma käe peale,',
        10: 'siis see saab ka juua Jumala kange viha viinast, mis segamata on valatud Tema viha karikasse; ja Teda peab vaevatama tules ja väävlis pühade Inglite ees ja Talle ees.',
        11: 'Ja nende valu suits tõuseb üles ajastute ajastuteni; ja ei ole rahu päevad ega ööd neil, kes kummardavad metsalist ja tema kuju ega neil, kes vastu võtavad tema nime märgi.',
        12: 'Siin on pühade kannatlikkus; siin on need, kes peavad Jumala käske ja Jeesuse usku!"',
        13: 'Ja ma kuulsin häält taevast ütlevat: "Kirjuta: õndsad on surnud, kes Issandas surevad nüüdsest peale; tõesti, ütleb Vaim, nad hingavad oma vaevadest, sest nende teod lähevad nendega ühes!"',
        14: 'Ja ma nägin: vaata, valge pilv ja see, kes pilve peal istus, oli Inimese Poja sarnane; Temal oli kuldpärg peas ja terav sirp käes.',
        15: 'Ja templist väljus teine Ingel ning hüüdis suure häälega sellele, kes istus pilve peal: "Pista sirp sisse ja põima, sest lõikuseaeg on tulnud, maa lõikus on ju valminud!"',
        16: 'Ja see, kes istus pilve peal, laskis oma sirbi käia üle maa, ja maa lõigati paljaks.',
        17: 'Ja teine Ingel väljus taeva templist, ja temalgi oli terav sirp käes.',
        18: 'Ja veel teine Ingel väljus altarist, ja temal oli võimus tule üle. Ja ta hüüdis suure häälega sellele, kellel oli terav sirp käes, ning ütles: "Pista sisse oma terav sirp ja lõika maha maa viinapuu tarjad, sest selle kobarad on küpsed!"',
        19: 'Ja Ingel laskis käia oma sirbi üle maa ja lõikas maa viinamäe paljaks ja viskas marjad Jumala kange viha suurde surutõrde.',
        20: 'Ja surutõrt sõtkuti väljaspool linna, ja tõrrest jooksis verd välja hobuste valjastest saadik tuhat kuussada vagu maad!',
    },
    15: {
        1: 'Ja ma nägin teist imetähte taevas, suurt ja imelist: seitse Inglit, kelle käes oli seitse viimset nuhtlust; sest nendega sai Jumala kange viha täielikuks.',
        2: 'Ja ma nägin otsekui klaasmerd segatud tulega ja neid, kes olid võitnud metsalise ja ta kuju ja ta nime arvu, seisvat klaasmere ääres, Jumala kandled käes.',
        3: 'Ja nad laulsid Jumala sulase Moosese laulu ja Talle laulu, öeldes: "Suured ja imelised on Sinu teod, Issand Jumal, Kõigeväeline! Õiged ja tõelised on Sinu teed, Sa rahvaste Kuningas!',
        4: 'Kes ei peaks kartma Sind, Issand, ja andma austust Sinu nimele? Sest Sina üksi oled püha; sest kõik paganad tulevad ja kummardavad Sind, sellepärast et Su õiged kohtuotsused on saanud avalikuks!"',
        5: 'Ja pärast seda ma nägin: tunnistustelgi tempel taevas avati.',
        6: 'Ja need seitse Inglit, kelle käes oli seitse nuhtlust, väljusid templist, riietatud puhta ja hiilgava lõuendiga ja rinde ümbert vöötatud kuldvööga.',
        7: 'Ja üks neist neljast olendist andis seitsmele Inglile seitse kuldkaussi täis kanget Jumala viha, kes elab ajastute ajastuteni.',
        8: 'Ja tempel sai täis suitsu Jumala aust ja Tema väest, ja ükski ei võinud sinna templisse sisse minna enne kui oli täide saadetud seitsme Ingli seitse nuhtlust.',
    },
    16: {
        1: 'Ja ma kuulsin suurt häält templis ütlevat seitsmele Inglile: "Minge ja valage Jumala kange viha kausid välja maa peale!"',
        2: 'Ja esimene läks ja valas oma kausi välja maa peale. Ja kurje ning ilgeid mädapaiseid tekkis inimeste külge, kellel oli metsalise märk ja kes kummardasid tema kuju.',
        3: 'Ja teine Ingel valas oma kausi välja merre, ja see sai otsekui surnu vereks, ja suri iga elav hing, kõik, kes meres olid.',
        4: 'Ja kolmas Ingel valas oma kausi välja jõgedesse ja veeallikaisse, ja need said vereks.',
        5: 'Ja ma kuulsin vete Inglit ütlevat: "Õige oled Sina, Kes oled ja Kes olid, ja Sina, Püha, et Sa nõnda oled kohut mõistnud!',
        6: 'Sest nemad on pühade ja prohvetite verd valanud, ja verd oled ka Sina neile juua andnud; nad on seda väärt!"',
        7: 'Ja ma kuulsin altarit ütlevat: tõesti, Issand Jumal, Sa Kõigeväeline, tõelised ja õiged on Sinu kohtuotsused!"',
        8: 'Ja neljas Ingel valas välja oma kausi päikese peale. Ja temale anti inimesi tulega kõrvetada.',
        9: 'Ja suur kuumus kõrvetas inimesi ja nemad pilkasid Jumala nime, Kelle meelevalla all on need nuhtlused, ega parandanud meelt, et nad Temale oleksid austust andnud.',
        10: 'Ja viies Ingel valas välja oma kausi metsalise aujärje peale. Ja tema kuningriik pimenes; ja nad närisid oma keelt valu pärast',
        11: 'ja pilkasid taeva Jumalat oma valude ja paisete pärast ega pöördunud oma tegudest.',
        12: 'Ja kuues Ingel valas välja oma kausi suure Eufrati jõe peale, ja selle vesi kuivas ära, et tee oleks valmis kuningaile, kes tulevad päevatõusu poolt.',
        13: 'Ja ma nägin lohe suust ja metsalise suust ja valeprohveti suust väljuvat kolm rüvedat vaimu otsekui konnad.',
        14: 'Need on nimelt kuradite tunnustähti tegevad vaimud, kes lähevad välja kõige ilmamaa kuningate juurde neid koguma sõtta Kõigeväelise Jumala suureks päevaks. -',
        15: 'Vaata, ma tulen kui varas! Õnnis see, kes valvab ja hoiab oma riideid, et ta ei käiks alasti ja et ei nähtaks Tema häbi. -',
        16: 'Ja need kogusid nad kokku ühte paika, mida heebrea keeles kutsutakse Harmagedooniks.',
        17: 'Ja seitsmes Ingel valas oma kausi välja õhku, ja suur hääl kostis taeva templist aujärjelt ning ütles: "See on sündinud!"',
        18: 'Ja sündis hääli ja müristamisi ja välke ja tekkis suur maavärisemine, millist ei ole olnud sest ajast, kui inimesi on olnud maa peal; säärane suur maavärisemine oli see.',
        19: 'Ja suur linn jagunes kolmeks osaks, ja paganrahvaste linnad langesid. Ja suurt Baabüloni tuletati meelde Jumala ees, et Jumal annaks temale oma raevuviina karika.',
        20: 'Ja kõik saared põgenesid ja mägesid ei leidunud enam.',
        21: 'Ja suuri raheteri, talendiraskusi, tuli taevast maha inimeste peale. Ja inimesed pilkasid Jumalat rahe nuhtluse pärast; sest selle nuhtlus oli väga vali.',
    },
    17: {
        1: 'Siis tuli üks seitsmest Inglist, kelle käes olid need seitse kaussi, ja kõneles minuga ning ütles: "Tule, ma tahan sulle näidata suure hoora nuhtlemist, kes istub suurte vete peal,',
        2: 'kellega on hooranud ilmamaa kuningad ja kelle hooruse viinast on ilmamaa elanikud joobnuks saanud!"',
        3: 'Ka tema viis mind vaimus ära kõrbe. Seal ma nägin naist istuvat helkjaspunase metsalise seljas, kes oli täis pilkenimesid ja kellel oli seitse pead ja kümme sarve.',
        4: 'Ja naine oli riietatud purpuriga ja helkjaspunase riidega ning ehitud kulla ja kalliskivide ja pärlitega, ja temal oli käes kuldkarikas täis jälkusi ja oma hooruse saasta.',
        5: 'Ja tema otsaesisele oli kirjutatud nimi, saladus: "Suur Baabülon, ilmamaa hoorade ja jälkuste ema!"',
        6: 'Ja ma nägin naise olevat joobnud pühade verest ja Jeesuse tunnistajate verest. Ja ma imestasin üliväga teda nähes.',
        7: 'Ja Ingel ütles mulle: "Mispärast sa imestad? Ma ütlen sulle saladuse naisest ja metsalistest, kes naist kannab ja kellel on seitse pead ja kümme sarve.',
        8: 'Metsaline, keda sa nägid, on olnud, ja teda ei ole enam; aga ta tuleb sügavusest üles ja läheb hukatusse; ja ilmamaa elanikud, kelle nimed ei ole kirjutatud eluraamatusse maailma asutamisest alates, imestavad metsalist nähes, sest ta oli ja teda ei ole, aga ta tuleb jälle!',
        9: 'Siia kuulub mõistus, millel on tarkust. Need seitse pead on seitse mäge, millel naine istub, ja on seitse kuningat:',
        10: 'viis on neist langenud, üks on alles, ja teine ei ole veel tulnud. Kui ta tuleb, peab ta jääma natukeseks ajaks.',
        11: 'Ja metsaline, kes on olnud ja keda ei ole enam, on ise kaheksas ja ühtlasi üks neist seitsmest, ja ta läheb hukatusse.',
        12: 'Ja need kümme sarve, mis sa nägid, on kümme kuningat, kes ei ole veel saanud valitsust, aga nad saavad võimu kui kuningad üheks tunniks ühes metsalisega.',
        13: 'Neil on üks ja sama nõu, ja nad annavad metsalise kätte oma väe ja võimu.',
        14: 'Nemad hakkavad sõdima Tallega, ja Tall võidab nad ära, sest Tema on isandate Isand ja kuningate Kuningas, ja ühes Temaga võidavad need, kes on kutsutud ja valitud ja ustavad!"',
        15: 'Ja ta ütles mulle: "Veed, mis sa nägid seal, kus hoor istub, on rahvad ja rahvahulgad ja rahvahõimud ja keeled.',
        16: 'Ja need kümme sarve, mis sa nägid, ja metsaline, need vihkavad hoora ja teevad tema puupaljaks ja alasti ja söövad tema liha ja põletavad ta ära tulega.',
        17: 'Sest Jumal on neile andnud südamesse teha Tema nõu järgi ja heita ühte nõusse ning anda Oma kuninglik valitsus metsalise kätte, kuni täituvad Jumala sõnad.',
        18: 'Ja naine, keda sa nägid, on suur linn, kelle käes on valitsus ilmamaa kuningate üle!"',
    },
    18: {
        1: 'Pärast seda ma nägin teist Inglit taevast maha tulevat, ja temal oli suur meelevald; ja ilmamaa läks valgeks tema auhiilgusest.',
        2: 'Ja tema hüüdis võimsa häälega ning ütles: "Langenud, langenud on suur Baabülon ja on saanud kurjade vaimude eluasemeks ja kõigi rüvedate vaimude ulualuseks ja kõigi rüvedate ja vihatud lindude pesapaigaks!',
        3: 'Sest tema hooruskiima viina on joonud kõik rahvad, ja ilmamaa kuningad on temaga hooranud ja ilmamaa kaupmehed on tema liiast toredusest rikkaks saanud!"',
        4: 'Ja ma kuulsin teist häält taevast ütlevat: "Minge välja temast, Minu rahvas, et te ei saaks tema pattude osaliseks ja et teid ei tabaks tema nuhtlused!',
        5: 'Sest tema patud on ulatunud taevani ja Jumal on tuletanud meelde tema ülekohtused teod.',
        6: 'Makske temale kätte, nõnda nagu tema on kätte maksnud, ja tasuge temale kahekordselt tema tegusid mööda; karikasse, mille tema on täis valanud, valage temale kahekordselt;',
        7: 'nii palju kui tema on ülistanud iseennast ja taga ajanud toredust, niisama palju tehke temale piina ja leina. Sest ta ütleb oma südames: ma istun kui kuninganna ega ole lesk ega saa kunagi näha kurvastust!',
        8: 'Sellepärast tulevad ühel päeval tema nuhtlused: surm ja lein ja nälg, ja ta põletatakse ära tulega, sest vägev on Issand Jumal, kes on mõistnud kohut tema üle!',
        9: 'Ja teda uluvad taga ja kaebavad ilmamaa kuningad, kes temaga on hooranud ja toredasti elanud, kui nad näevad tema põlemise suitsu,',
        10: 'hirmu pärast tema piina ees kaugel seistes ning öeldes: "Häda, häda, Baabülon, sa suur linn, sa vägev linn, sest ühe silmapilguga on su kohus tulnud!"',
        11: 'Ja ilmamaa kaupmehed nutavad ja leinavad tema pärast, sest keegi ei osta enam nende kaupa:',
        12: 'ei kaubaks toodud kulda, ei hõbedat, ei kalliskive, ei pärleid, ei kallist lõuendit, ei purpurit, ei siidi, ei helkjaspunast riiet, ei mingisugust healõhnalist puud, ei mingisugust elevandiluust riista ega mingisugust kallimast puust riista, ei vasest, ei rauast ega marmorkivist riista,',
        13: 'ei kaneeli, ei juuksevõiet, ei suitsutusrohte, ei salvi, ei viirukit, ei viina, ei õli, ei peenikest jahu, ei nisu, ei veiseid, ei lambaid, ei hobuseid, ei tõldu, ei orje ega inimhingi!',
        14: 'Ja puuvili, mida su hing ihaldas, on su käest ära läinud, ja kõik, mis lihav ja läikiv, on su käest ära läinud, ja seda sa enam ei leia!',
        15: 'Nende asjade kaupmehed, kes selle linna kaudu rikkaks said, seisavad kaugel hirmu pärast tema piina ees, nuttes ja leinates,',
        16: 'ja ütlevad: "Häda, häda, sa suur linn, kes olid riietatud kalli lõuendi ja purpuri ja helkjaspunase riidega ning olid ilustatud kulla ja kalliskivide ja pärlitega, sest ühe silmapilguga on nii suur rikkus hävitatud!"',
        17: 'Ja kõik tüürimehed ja kõik rannasõidu-laevnikud ja meremehed ja kõik, kes merel sõidavad, seisid eemal',
        18: 'ja kisendasid, kui nad nägid tema põlemise suitsu, ning ütlesid: "Kes on selle suure linna sarnane?"',
        19: 'Ja nad puistasid põrmu pea peale ja kisendasid nuttes ja leinates ning ütlesid: "Häda häda, sa suur linn, kelle varaga on rikkaks saanud kõik, kellel oli laevu merel - ühe silmapilguga on ta hävitatud!"',
        20: 'Rõõmutsege temast, taevas ja pühad ja Apostlid ja prohvetid! Sest Jumal on teie kohtu mõistnud tema kätte!',
        21: 'Ja üks tugev Ingel tõstis kivi, nagu suure veskikivi, ja viskas selle merre, öeldes: "Nõnda visatakse suur linn Baabülon äkitselt ära ja teda ei leita enam!',
        22: 'Su sees ei ole enam kuulda kandlelööjate ja mängumeeste ja vileajajate ja pasunapuhujate häält ega leidu sinus enam ühtki ametimeest; ja enam ei kosta su sees veski mürin;',
        23: 'su sees ei paista enam küünlavalgus, ei ole enam kuulda peigmehe ega pruudi häält su sees! Sest sinu kaupmehed olid maa suured isandad, sinu nõidusega on kõik rahvad viidud eksitusse!',
        24: 'Temast on leitud prohvetite ja pühade verd ja kõikide verd, kes on tapetud maa peal!"',
    },
    19: {
        1: 'Pärast seda ma kuulsin otsekui hulga rahva suurt häält taevast ütlevat: "Halleluuja! Õnnistus ja austus ja vägi olgu meie Jumalale!',
        2: 'Sest tõelised ja õiged on Tema kohtud, et Ta on kohut mõistnud suure hoora üle, kes rikkus ilmamaa oma hooraeluga, ja on Oma sulaste vere temale kätte maksnud!"',
        3: 'Ja nad ütlesid teist korda: "Halleluuja!" Ja tema suits tõuseb üles ajastute ajastuteni.',
        4: 'Ja need kakskümmend neli olendit heitsid maha ja kummardasid Jumalat, kes aujärjel istub ja ütlesid: "Aamen, halleluuja!"',
        5: 'Ja aujärjelt kostis hääl, mis ütles: "Kiitke meie Jumalat, kõik Tema sulased, kes Teda kardate, nii pisukesed kui suured!"',
        6: 'Ja ma kuulsin otsekui hulga rahva häält ja otsekui suurte vete kohinat ja otsekui kange pikse müristamist, ütlevat: "Halleluuja! Sest Issand, meie Kõigeväeline Jumal, on võtnud kuningliku valitsuse Oma kätte!',
        7: 'Rõõmutsegem ja hõisakem ning andkem Temale austust! Sest Talle pulmad on tulnud ja Tema naine on ennast valmistanud!',
        8: 'Ja naisele anti riietumiseks hiilgav ja puhas lõuend. See lõuend on pühade õiged teod!"',
        9: 'Ja Ingel ütles mulle: "Kirjuta: õndsad on need, kes Talle pulma õhtusöömaajale on kutsutud!" Ja tema ütles veel mulle: "Need on tõelised Jumala sõnad!"',
        10: 'Ja ma heitsin maha tema jalge ette, et teda kummardada, aga tema ütles mulle: "Vaata, ära tee seda! Ma olen sinu ja nende su vendade kaassulane, kellel on Jeesuse tunnistus. Kummarda Jumalat, sest Jeesuse tunnistus on prohvetikuulutamise vaim!"',
        11: 'Ja ma nägin taeva avatud, ja vaata: valge hobune! Ja Selle nimi, Kes tema seljas istus, on Ustav ja Tõeline, ja Tema mõistab kohut ja sõdib õiguses.',
        12: 'Aga Tema silmad olid tuleleek ja Temal oli peas palju ehissidemeid; ja Temale oli kirjutatud nimi, mida ei tea keegi muu kui Tema Ise.',
        13: 'Ja Temal oli seljas verega kastetud kuub ja Tema nimeks on pandud Jumala Sõna.',
        14: 'Ja sõjaväed taevas järgisid Teda valgete hobuste seljas ja olid riietatud valge ja puhta lõuendiga.',
        15: 'Ja Tema suust tuli välja terav mõõk, et sellega lüüa rahvaid. Ja Tema Ise karjatab neid raudkepiga. Ja Ta ise sõtkub kõigeväelise Jumala tulise viha viina surutõrt.',
        16: 'Ja Temale on Tema kuue ja puusa peale kirjutatud nimi: "Kuningate Kuningas ja isandate Issand!"',
        17: 'Ja ma nägin üht Inglit seisvat päikeses ja see kisendas suure häälega ning hüüdis kõigile kesktaeva kohal lendavaile lindudele: "Tulge ja lennake kokku suurele Jumala söömaajale',
        18: 'sööma kuningate liha ja ülemate pealikute liha ja vägevate liha ja hobuste ja nende seljas istujate liha ja kõigi vabade ja orjade ja pisukeste ja suurte liha!"',
        19: 'Ja ma nägin metsalist ja ilmamaa kuningaid ja nende sõjaväge olevat kogunenud sõda pidama Sellega, Kes istus hobuse seljas, ja Tema sõjaväega.',
        20: 'Ja metsaline võeti kinni ja temaga ühes valeprohvet, kes tema ees oli teinud oma imeteod, millega ta oli eksitanud neid, kes metsalise märgi olid vastu võtnud ja kes kummardasid tema kuju. Nad mõlemad visati elusalt tulejärve, mis põleb väävliga.',
        21: 'Ja teised tapeti mõõgaga, mis lähtus Selle suust, Kes istus hobuse seljas. Ja kõigi lindude kõhud said täis nende lihast.',
    },
    20: {
        1: 'Ja ma nägin Ingli taevast maha tulevat; sellel oli sügaviku võti ja suured ahelad käes.',
        2: 'Ja ta võttis kinni lohe, vana mao, see on Kuradi ehk Saatana, ja sidus ta ahelaisse tuhandeks aastaks',
        3: 'ja heitis ta sügavikku ja pani ta luku taha ja vajutas pealepoole teda pitseri, et ta enam ei eksitaks rahvaid, kuni need tuhat aastat otsa saavad. Pärast seda peab teda natukeseks ajaks lahti lastama.',
        4: 'Ja ma nägin aujärgi ja neid, kes nendel istusid; ja kohus anti nende kätte; ja ma nägin nende hingi, kelle pead olid ära raiutud Jeesuse tunnistuse ja Jumala sõna pärast ja kes ei olnud kummardanud metsalist ega tema kuju ega olnud võtnud tema märki oma otsaesisele ja oma käe peale. Ja nad virgusid ellu usus ja valitsesid kuningikult ühes Kristusega tuhat aastat.',
        5: 'Aga muud surnud ei elustunud mitte, kuni need tuhat aastat otsa saavad. See on esimene ülestõusmine.',
        6: 'Õnnis ja püha on see, kellel on osa esimesest ülestõusmisest; nende üle ei ole teisel surmal meelevalda, vaid nad peavad olema Jumala ja Kristuse preestrid ja valitsema kuninglikult ühes Temaga need tuhat aastat.',
        7: 'Ja kui need tuhat aastat täis saavad, siis lastakse saatan lahti oma vangist.',
        8: 'Ja ta läheb välja eksitama rahvaid, kes elavad ilmamaa neljas nurgas, Googi ja Maagoogi, neid sõtta koguma. Nende arv on nagu mereäärne liiv!',
        9: 'Ja nad tulid üles ilmamaa lagendikule ja piirasid ümber pühade leeri ja armastatud linna. Siis langes tuli taevast maha ja sõi nad ära!',
        10: 'Ja kurat, kes neid eksitas, heideti tule ja väävli järve, kus on ka metsaline ja valeprohvet. Ja neid vaevatakse päevad ja ööd ajastute ajastuteni!',
        11: 'Ja ma nägin suurt valget aujärge ja Seda, Kes sellel istub, Kelle palge eest põgenesid maa ja taevas, ja neile ei leitud aset.',
        12: 'Ja ma nägin surnuid, suuri ja pisukesi, seisvat aujärje ees, ja raamatud avati. Ja teine raamat avati, see on eluraamat. Ja surnutele mõisteti kohut sedamööda kuidas raamatuisse oli kirjutatud, nende tegude järgi.',
        13: 'Ja meri andis tagasi need surnud, kes temas olid, ja surm ja surmavald andsid tagasi surnud, kes neis olid, ja igaühele mõisteti kohut tema tegude järgi.',
        14: 'Ja surm ja surmavald heideti tulejärve! See on teine surm, tulejärv.',
        15: 'Ja keda ei leitud kirjutatud olevat eluraamatusse, heideti tulejärve!',
    },
    21: {
        1: 'Ja ma nägin uut taevast ja uut maad; sest esimene taevas ja esimene maa olid kadunud ja merd ei olnud enam.',
        2: 'Ja ma nägin püha linna, uut Jeruusalemma, taevast Jumala juurest maha tulevat, valmistunud otsekui pruut, kaunistatud oma mehele.',
        3: 'Ja ma kuulsin suurt häält aujärjelt ütlevat: "Vaata, Jumala telk on inimeste juures! Ja Tema asub nende juurde elama ja nemad on Tema rahvad ja Jumal Ise on nendega.',
        4: 'Ja Tema pühib ära kõik pisarad nende silmist, ja surma ei ole enam ega leinamist ega kisendamist ega vaeva ei ole enam. Sest endised asjad on möödunud!"',
        5: 'Ja Kes aujärjel istus, ütles: "Vaata, Ma teen kõik uueks!" Ja Ta ütles: "Kirjuta, sest need sõnad on ustavad ja tõelised!"',
        6: 'Ja Ta ütles mulle: "See on sündinud! Mina olen A ja O, algus ja ots. Mina annan sellele, kellel on janu, eluvee allikast ilma hinnata.',
        7: 'Kes võidab, see pärib selle, ja Mina olen temale Jumalaks ja tema on Minule pojaks.',
        8: 'Aga argade ja uskmatute ja jälkide ja tapjate ja hoorajate ja nõidade ja ebajumalateenijate ja kõigi valelike osa on tule ja väävliga põlevas järves! See on teine surm."',
        9: 'Ja minu juurde tuli üks seitsmest Inglist, kelle käes olid need seitse kaussi, täis seitset viimset nuhtlust; ja ta rääkis minuga ning ütles: "Tule, ma näitan sulle mõrsjat, Talle naist!"',
        10: 'Ja tema kandis mind vaimus suure ja kõrge mäe otsa ja näitas mulle linna, püha Jeruusalemma, mis oli maha tulemas taevast Jumala juurest',
        11: 'ja millel on Jumala auhiilgus; ja tema valgus on kõige kallima kivi sarnane, otsekui jaspiskivi, mis hiilgab nagu mägikristall.',
        12: 'Linnal on suur ja kõrge müür ja kaksteist väravat ja väravate peal kaksteist Inglit; ja väravate peale on kirjutatud nimed. Need on kaheteistkümne Iisraeli laste suguharu nimed.',
        13: 'Ida pool on kolm väravat, põhja pool kolm väravat, lõuna pool kolm väravat, lääne pool kolm väravat.',
        14: 'Ja linna müüril on kaksteist aluskivi ja nende peal Talle kaheteistkümne Apostli nimed.',
        15: 'Ja sellel, kes minuga rääkis, oli käes kuldpilliroog, et mõõta linna ja tema väravaid ja tema müüri.',
        16: 'Ja linn on nelinurkne ja tema pikkus on niisama suur kui tema laius. Ja ta mõõtis linna pillirooga kaksteist tuhat vagu. Tema pikkus ja laius ja kõrgus on võrdsed.',
        17: 'Ja ta mõõtis tema müüri - sada nelikümmend neli küünart, inimese mõõdu järgi, mis on Ingli mõõt.',
        18: 'Ja tema müüri alusehitus oli jaspiskivist ja linn puhtast kullast, selge klaasi sarnane.',
        19: 'Ja linna müüri aluskivid olid ehitud kõiksuguste kalliskividega. Esimene aluskivi oli jaspis, teine safiir, kolmas kaltsedoon, neljas smaragd,',
        20: 'viies sardoonüks, kuues sardion, seitsmes krüsoliit, kaheksas berüll, üheksas topaas, kümnes krüsopraas, üheteistkümnes hüatsint, kaheteistkümnes ametüst.',
        21: 'Ja need kaksteist väravat olid kaksteist pärlit: iga värav oli ühest pärlist ja linna tänav selgest kullast otsekui läbipaistev klaas.',
        22: 'Ja templit ma seal ei näinud, sest Issand, kõigeväeline Jumal, on tema tempel, ja Tall.',
        23: 'Ja linnale ei ole tarvis päikest ega kuud, et need seal paistaksid; sest Jumala auhiilgus valgustab teda ja tema lamp on Tall.',
        24: 'Ja rahvad hakkavad käima tema valguses, ja ilmamaa kuningad toovad sinna oma auhiilguse.',
        25: 'Ja tema väravaid ei suleta päeval, aga ööd seal ei olegi.',
        26: 'Ja rahvaste auhiilgus ja kallisvarad tuuakse sinna sisse.',
        27: 'Aga sinna sisse ei pääse midagi, mis ei ole puhas, ei keegi, kes teeb jälkusi ja valet, vaid üksnes need, kes on kirjutatud Talle eluraamatusse.',
    },
    22: {
        1: 'Ja ta näitas mulle puhast eluveejõge, selget nagu mägikristall. See voolas välja Jumala ja Talle aujärjest.',
        2: 'Keset linna tänavat ja mõlemal pool jõge oli elupuu; see kandis vilja kaksteist korda, igas kuus andes oma vilja. Ja puu lehed tulid terviseks rahvastele.',
        3: 'Ja midagi neetut ei ole enam. Ja Jumala ja Talle aujärg on siis seal, ja Tema sulased teenivad Teda.',
        4: 'Ja nad näevad Tema palet, ja Tema nimi on nende otsaesisel.',
        5: 'Ja ööd ei ole enam, ja neile ei ole vaja lambivalgust ega päevavalget, sest Issand Jumal valgustab neid, ja nemad valitsevad ajastute ajastuteni.',
        6: 'Ja Ta ütles mulle: "Need on ustavad ja tõelised sõnad! Ja Issand, prohvetite hingede Jumal, on läkitanud Oma Ingli Oma sulastele näitama, mis peab varsti sündima.',
        7: 'Ja vaata, Ma tulen nobedasti! Õnnis see, kes peab selle raamatu ennustuse sõnu!"',
        8: 'Ja mina, Johannes, olen see, kes seda kuulis ja nägi. Ja kui ma seda olin kuulnud ja näinud, ma heitsin maha, kummardama Ingli jalgade ette, kes mulle seda näitas.',
        9: 'Ja ta ütles mulle: "Vaata, ära tee seda! Sest ma olen sinu ja su vendade, prohvetite ja nende kaassulane, kes selle raamatu sõnu peavad. Kummarda Jumalat!"',
        10: 'Ja ta ütles mulle: "Ära pane pitseriga kinni selle raamatu ennustussõnu, sest aeg on ligidal!',
        11: 'Kes ülekohut teeb, tehku veel ülekohut, ja kes on rüve, see rüvetugu veel enam; aga kes on õige, tehku veel õigust, ja kes on püha, see pühitsegu ennast veel enam!',
        12: 'Vaata, Ma tulen pea, ja Mu palk on Minuga tasuda kätte igaühele nõnda nagu tema tegu on!',
        13: 'Mina olen A ja O, Esimene ja Viimne, algus ja ots!',
        14: 'Õndsad need, kes oma rüüd pesevad, et neil oleks meelevald süüa elupuust ja väravaist linna sisse minna!',
        15: 'Väljaspool on koerad ja nõiad ja hoorajad ja tapjad ja ebajumalateenijad ja kõik, kes valet armastavad ja teevad.',
        16: 'Mina, Jeesus, läkitan Oma Ingli teile seda tunnistama kogudustes! Mina olen Taaveti juur ja sugu, helkjas koidutäht!"',
        17: 'Ja Vaim ja pruut ütlevad: "Tule!" Ja kes seda kuuleb, öelgu: "Tule!" Ja kellel on janu, tulgu; ja kes tahab, võtku eluvett ilma hinnata!',
        18: 'Mina tunnistan kõikidele, kes kuulevad selle raamatu ennustussõnu: kui keegi neile midagi juurde lisab, siis paneb Jumal tema peale nuhtlused, mis selles raamatus on kirja pandud!',
        19: 'Ja kui keegi võtab midagi ära selle prohvetiraamatu sõnadest, siis Jumal võtab ära tema osa elupuust ja pühast linnast, millest on kirjutatud selles raamatus!',
        20: 'Tema, kes seda tunnistab ütleb: "Tõesti, Mina tulen varsti!" Aamen, tule, Issand Jeesus!',
        21: 'Issanda Jeesuse Kristuse arm olgu kõikidega! Aamen.',
    },
}
